INSERT INTO knowledge_documents (title, content, source, category, tags, isActive, createdAt, updatedAt) 
VALUES 
('المجلس الإسلامي الأعلى - الصلاحيات', 'كان للمجلس الإسلامي الأعلى صلاحيات واسعة في إدارة الأوقاف والمحاكم الشرعية والشؤون الدينية في فلسطين.', 'تاريخ المجلس الإسلامي الأعلى', 'historical', 'المجلس الإسلامي، الصلاحيات، الإدارة', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الحاج أمين الحسيني - رئيس المجلس الإسلامي', 'ترأس الحاج أمين الحسيني المجلس الإسلامي الأعلى وعمل على تطوير الأوقاف وترميم المسجد الأقصى.', 'سيرة الحاج أمين الحسيني', 'historical', 'الحاج أمين، المجلس الإسلامي، الأقصى', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('ترميم المسجد الأقصى - الفترة البريطانية', 'قام المجلس الإسلامي الأعلى بترميمات واسعة للمسجد الأقصى في الثلاثينيات، ممولة من تبرعات المسلمين وريع الأوقاف.', 'تاريخ ترميم الأقصى', 'historical', 'ترميم الأقصى، المجلس الإسلامي، التبرعات', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الأوقاف في الضفة الغربية - الإدارة الأردنية', 'أدارت الأردن الأوقاف في الضفة الغربية من 1948 إلى 1967 وفق قانون الأوقاف الأردني رقم 23 لسنة 1964.', 'تاريخ الأوقاف في الضفة الغربية', 'historical', 'الإدارة الأردنية، الضفة الغربية، الأوقاف', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الأوقاف بعد 1967 - الاحتلال الإسرائيلي', 'استولت إسرائيل على العديد من الأوقاف في القدس والضفة الغربية بعد 1967، وفرضت قيوداً على إدارتها.', 'الأوقاف تحت الاحتلال', 'historical', 'الاحتلال، الاستيلاء، القدس', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('حارة المغاربة - الهدم', 'هدمت إسرائيل حارة المغاربة الوقفية بالكامل عام 1967، وشردت سكانها لإنشاء ساحة البراق.', 'تاريخ حارة المغاربة', 'historical', 'حارة المغاربة، الهدم، الاحتلال', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('وقف أبو مدين الغوث - القدس', 'وقف أبو مدين الغوث من أقدم الأوقاف في القدس، ويشمل عقارات ومساجد ومدارس، وتعرض للاستيلاء الإسرائيلي.', 'أوقاف القدس التاريخية', 'historical', 'أبو مدين، الأوقاف، القدس', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الفقه المالكي - تعريف الوقف', 'الوقف في المذهب المالكي هو جعل المنفعة للموقوف عليه ولو في المآل، مع بقاء العين على ملك الواقف أو على حكم ملكه.', 'الفقه المالكي - كتاب الوقف', 'jurisprudence', 'الفقه المالكي، تعريف الوقف، المنفعة', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الفقه الشافعي - تعريف الوقف', 'الوقف في المذهب الشافعي هو حبس مال يمكن الانتفاع به مع بقاء عينه، بقطع التصرف في رقبته على مصرف مباح موجود.', 'الفقه الشافعي - كتاب الوقف', 'jurisprudence', 'الفقه الشافعي، تعريف الوقف، حبس المال', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الفقه الحنبلي - تعريف الوقف', 'الوقف في المذهب الحنبلي هو تحبيس الأصل وتسبيل المنفعة، فتحبس العين ويسبل نفعها في سبيل الخير.', 'الفقه الحنبلي - كتاب الوقف', 'jurisprudence', 'الفقه الحنبلي، تعريف الوقف، تحبيس الأصل', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573));